/// <summary>
/// Extension of TAMRebateDeal form
/// </summary>
[ExtensionOf(formStr(TAMRebateDeal))]
internal final class METTAMRebateDealFrm_Extension
{
}

Method.Source:
/// <summary>
/// Init method from Form
/// </summary>
public void init()
{
    next init();
    // CB705_VendorRebatePosting
    FormDataSource tamRebateDeal_ds = this.dataSource(FormDatasourceStr(TAMRebateDeal, TAMRebateDeal));
    FormDataSource tamRebateTable_ds = this.dataSource(FormDatasourceStr(TAMRebateDeal, TAMRebateTable));

    // CB705_VendorRebatePosting
    /*FormControl vendAccount = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDeal_METVendAccount)) as FormControl;        
    FormControl extRef = this.design().controlName(formControlStr(TAMRebateDeal, METExternalRebateDealReference)) as FormControl;
    FormControl priceComponentCode = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METPriceComponentCode)) as FormControl;
    FormControl priceAttributeGroupCombination = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METPriceAttributeGroupCombination)) as FormControl;
    FormControl headerPriceAttributeGroup = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METHeaderPriceAttributeGroup)) as FormControl;*/
    FormDataObject vendAccount = tamRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount));
    FormDataObject extRef = tamRebateDeal_ds.object(fieldNum(TAMRebateDeal, METExternalRebateDealReference));
    FormDataObject priceComponentCode = tamRebateTable_ds.object(fieldNum(TAMRebateTable, METPriceComponentCode));
    FormDataObject priceAttributeGroupCombination = tamRebateTable_ds.object(fieldNum(TAMRebateTable, METPriceAttributeGroupCombination));
    FormDataObject headerPriceAttributeGroup = tamRebateTable_ds.object(fieldNum(TAMRebateTable, METHeaderPriceAttributeGroup));

    FormControl headerPriceAttributeGroupDetail = this.design().controlName(formControlStr(TAMRebateDeal, METHeaderPriceAttributeGroupDetail)) as FormControl;
    FormControl linePriceAttributeGroup = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METLinePriceAttributeGroup)) as FormControl;
    FormControl linePriceAttributeGroupDetail = this.design().controlName(formControlStr(TAMRebateDeal, METLinePriceAttributeGroupDetail)) as FormControl;

    if (this.args().menuItemName() == menuitemdisplaystr(TAMRebateDealListPageVendRebate))
    {
        vendAccount.visible(true);
        extRef.visible(true);
        priceComponentCode.visible(false);
        priceAttributeGroupCombination.visible(false);
        headerPriceAttributeGroup.visible(false);
        headerPriceAttributeGroupDetail.visible(true);
        linePriceAttributeGroup.visible(false);
        linePriceAttributeGroupDetail.visible(true);
    }
    else
    {
        vendAccount.visible(true);
        extRef.visible(false);
        priceComponentCode.visible(false);
        priceAttributeGroupCombination.visible(false);
        headerPriceAttributeGroup.visible(false);
        headerPriceAttributeGroupDetail.visible(false);
        linePriceAttributeGroup.visible(false);
        linePriceAttributeGroupDetail.visible(false);
    }

}

/// <summary>
/// Bug 293485: CB201- Transaction type field is non editable when creating a new deal, until we reload the webpage for finops
/// Moving/refactoring from METTAMRebateDeal_TAMRebateTable_Extension\active to here 
/// </summary>
public void enableFields()
{
    void fieldAllowEdit(FormDataSource _fds, FieldId _fieldId, boolean _allowEdit)
    {
        _fds.object(_fieldId).allowEdit(_allowEdit);
        _fds.object(_fieldId).skip(!_allowEdit);
    }

    next enableFields();

    boolean allowEditTierLineTypeValue = !TAMRebateDeal.METVolumetricTierDeal 
                                      || (TAMRebateDeal.METVolumetricTierDeal && TAMRebateTable.METTierLineType == METTierLineType::Value);

    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, METAvgBy454Week), allowEditTierLineTypeValue);        

    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, UnitId), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, MinimumAmount), allowEditTierLineTypeValue);

    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, Category), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, RebatePostingId), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, GuaranteePostingId), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, DocumentNotes), allowEditTierLineTypeValue);

    FormControl calculationGroup = this.design().controlName(formControlStr(TAMRebateDeal, Calculation));
    calculationGroup.allowEdit(allowEditTierLineTypeValue);

    // calculation group
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeCreditNote), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, PaidInvoices), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, SupportNegativeTier), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeDiscountedAmount), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeSettlementDiscount), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeTax), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeFreeText), !TAMRebateDeal.METVolumetricTierDeal);

    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebatePer), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebatePeriodCode), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebateClaimPer), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebateClaimBy), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, ProcessPosting), allowEditTierLineTypeValue);

    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, RebateBasis), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, CalculationMethod), allowEditTierLineTypeValue);

    // Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
    // Transaction type not editable when use external sales data
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, SourceType), !TAMRebateDeal.METUseExternalSellData);
}

/// <summary>
/// Bug 293485: CB201- Transaction type field is non editable when creating a new deal, until we reload the webpage for finops
/// Moving/refactoring buttons logic from METTAMRebateDeal_TAMRebateTable_Extension\active to here
/// </summary>
public void enableButtons()
{       
    next enableButtons();

    boolean allowEditTierLineTypeRate = !TAMRebateDeal.METVolumetricTierDeal
                                     || (TAMRebateDeal.METVolumetricTierDeal && TAMRebateTable.METTierLineType == METTierLineType::Rate);

    AddLine.enabled(allowEditTierLineTypeRate);
    RemoveLine.enabled(allowEditTierLineTypeRate);
}
